import React, { useEffect } from "react";
import styled from "styled-components";

interface AlertPopupProps {
  title: string;
  message: string;
  onClose: () => void;
}

const Overlay = styled.div`
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(3px);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 3000;
`;

const Modal = styled.div`
  background: #ffffff;
  width: 380px;
  padding: 26px;
  border-radius: 16px;
  text-align: center;
  animation: fadeIn 0.25s ease-out;

  @keyframes fadeIn {
    from { opacity: 0; transform: translateY(10px); }
    to   { opacity: 1; transform: translateY(0px); }
  }
`;

const Title = styled.h3`
  font-size: 20px;
  font-weight: 700;
  color: #4a5074;
  margin-bottom: 10px;
`;

const Message = styled.p`
  font-size: 15px;
  color: #333;
  margin-bottom: 22px;
`;

const OkButton = styled.button`
  background: #4a5174;   /* Theme purple */
  color: white;
  padding: 10px 22px;
  border-radius: 8px;
  border: none;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;

  &:hover {
    background: #3d4464;
  }
`;

const AlertPopup: React.FC<AlertPopupProps> = ({ title, message, onClose }) => {

  // Auto-close in 5 seconds
  useEffect(() => {
    const timer = setTimeout(() => {
      onClose();
    }, 5000);

    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <Overlay>
      <Modal>
        <Title>{title}</Title>
        <Message>{message}</Message>

        <OkButton onClick={onClose}>OK</OkButton>
      </Modal>
    </Overlay>
  );
};

export default AlertPopup;
